# IMPERIA COLD WAR — Researched Greece replacement concept, pending approval.
"""Design data only. Never writes into loaded game directories."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[2]
P='COLDWAR_GRE_R2_'
GROUPS=[('constitution','The Constitutional Question',4,0,8),('economy','Growth and Development',12,0,12),('defence','Armed Forces',22,0,12),('foreign','External Relations',34,0,11),('cyprus','Cyprus and the Guarantors',44,0,17),('junta','The Military Government',4,11,9),('right','The Conservative Right',12,11,8),('centre','The Liberal Centre',20,11,5),('socialist','National and Social Change',28,11,7),('left','The Communist Left',36,11,6),('crown','The Crown',44,11,5)]
PARTIES={22:('Military Government of 21 April','nationalist_military_junta_are_in_power'),1:('National Radical Union','western_conservatism_are_in_power'),2:('Centre Union','western_liberals_are_in_power'),3:('Panhellenic Liberation Movement','western_social_democrats_are_in_power'),4:('Communist Party of Greece','emerging_communist_state_are_in_power'),23:('Royalists','nationalist_monarchists_are_in_power')}

def mod(name,**values):return {'type':'modifier','spirit':name,'values':values}
def building(state,kind,levels=1):return {'type':'building','state':state,'building':kind,'levels':levels,'shared_slots':levels,'guards':['Owned and controlled by Greece','Native building cap and state capacity','One-time asset and slot receipt']}
def research(category,bonus=.5,uses=1):return {'type':'research','category':category,'bonus':bonus,'uses':uses}
def doctrine(category='land_doctrine',bonus=.25,uses=1):return {'type':'doctrine','category':category,'bonus':bonus,'uses':uses}
def remove(name):return {'type':'remove_spirit','name':name}
def offer(key):return {'type':'offer','key':key}
def xp(service,value):return {'type':'experience','service':service,'value':value}
def action(text,code):return {'type':'native_action','text':text,'code':code}
def temporary(name,days,**values):return {'type':'temporary','spirit':name,'days':days,'values':values}

def build():
 nodes=[]
 def add(group,key,title,dx,y,pre=(),ex=(),effects=(),cost=5,setup=0,weekly=0,party=None,require='',desc='',source='history',leader=None):
  g=next(g for g in GROUPS if g[0]==group)
  slot=party if party is not None else {'junta':22,'right':1,'centre':2,'socialist':3,'left':4,'crown':23}.get(group)
  nodes.append({'key':key,'id':P+key,'group':group,'title':title,'x':g[2]+dx,'y':g[3]+y,'prerequisites':[list(t)if isinstance(t,(tuple,list))else[t]for t in pre],'exclusive':list(ex),'cost':cost,'days':cost*7,'setup_gdp_percent':setup,'weekly_gdp_percent':weekly,'effects':list(effects),'party_slot':slot,'party_trigger':PARTIES[slot][1]if slot else None,'required_party':PARTIES[slot][0]if slot else None,'leader':leader,'requirements':require,'description':desc,'source':source})

 # Eight constitutional focuses. Alternative party programmes have independent native party gates.
 add('constitution','constitution','The Constitution in Abeyance',0,0,effects=[mod('Constitutional Administration',political_power_factor=.10,bureaucracy_cost_multiplier_modifier=.05)],cost=2,desc='The regime invokes the 1968 constitution while retaining exceptional powers. A functioning administration cannot settle the unresolved question of who may govern.')
 add('constitution','entrench','Entrench the Revolution',-2,1,pre=['constitution'],ex=['handover'],party=22,effects=[mod('Constitutional Administration',political_power_factor=.15,stability_factor=-.05),xp('army',25)],desc='The officers retain the final political veto. Their command becomes firmer while the exclusion of civilian constituencies deepens.')
 add('constitution','handover','Negotiate a Civilian Handover',2,1,pre=['constitution'],ex=['entrench'],effects=[temporary('Negotiated Military Withdrawal',180,army_org_factor=-.05,political_power_factor=-.10),mod('Constitutional Administration',stability_factor=.08)],require='A civilian transfer is being negotiated, or a civilian party already governs.',desc='A transfer of authority requires guarantees to the services and a credible opening for the opposition. A negotiated departure avoids making another military conspiracy the foundation of civilian rule.')
 add('constitution','tribunals','Retain the Exceptional Courts',-2,2,pre=['entrench'],party=22,effects=[mod('Constitutional Administration',foreign_influence_defense_modifier=.15,research_speed_factor=-.05)],desc='Military jurisdiction protects the government from organized opposition. The same restrictions isolate universities and weaken the free circulation of expertise.')
 add('constitution','amnesty','Political Amnesty and Open Courts',2,2,pre=['handover'],effects=[remove('Suppressed Political Life'),mod('Constitutional Administration',political_power_factor=-.05)],desc='Political prisoners must be released and ordinary courts restored before parliamentary competition can be credible. The executive relinquishes instruments that made governing without consent easier.')
 add('constitution','election','A Free Parliamentary Mandate',2,3,pre=['amnesty'],effects=[action('Enable free elections','set_politics = { elections_allowed = yes }'),remove('Emergency Rule'),research('CAT_industry',.5,1)],require='Exceptional military rule has ended. Use the existing party and election system.',desc='Legal political competition restores the distinction between a government and the state. The electorate chooses a cabinet through the existing parliamentary institutions rather than a prescribed successor.')
 add('constitution','republic','A Parliamentary Republic',0,5,pre=['election'],ex=['constitutional_crown'],effects=[mod('Constitutional Settlement',political_power_factor=.15,foreign_influence_defense_modifier=.10,stability_factor=-.03),remove('Civil War Inheritance')],desc='A free constitutional settlement removes the Crown as an independent center of executive authority. The change resolves one old division while alienating committed royalists.')
 add('constitution','constitutional_crown','A Crown Bound by Parliament',4,5,pre=['election'],ex=['republic'],effects=[mod('Constitutional Settlement',stability_factor=.10,navy_org_factor=.05,political_power_factor=-.10),remove('Civil War Inheritance')],desc='A freely accepted monarchy can offer continuity only if its powers are defined by parliament. Restraint on the government is the price of reconciling royalist institutions with elected authority.')

 # Twelve shared economic focuses, preserving the prosperous but uneven late-1960s starting point.
 add('economy','development','The Development Programme',0,0,effects=[mod('Development Strategy',production_speed_buildings_factor=.10,bureaucracy_cost_multiplier_modifier=.05)],setup=.5,source='economy',desc='Public coordination has supported rapid expansion, but production and infrastructure remain unevenly distributed. The development programme must turn investment into a broader productive base.')
 add('economy','technical','Technical Schools and Returning Skills',0,1,pre=['development'],effects=[remove('Emigration and Technical Gaps'),research('CAT_industry',.5,2)],setup=1,source='economy',desc='Greece needs technicians at home as well as the remittances of workers abroad. Technical schools and recognition of returning workers skills reduce dependence on a narrow pool of specialists.')
 add('economy','visitor_credit','Credit for the Visitor Economy',-2,2,pre=['technical'],ex=['industrial_credit'],effects=[mod('Development Strategy',office_park_income_tax_modifier=.15,production_speed_industrial_complex_factor=-.05),building(143,'offices')],setup=1,source='economy',desc='Hotels, transport services and coastal businesses earn foreign exchange quickly. Directing scarce credit toward visitors leaves less capital for industrial diversification.')
 add('economy','industrial_credit','Credit for Industrial Investment',2,2,pre=['technical'],ex=['visitor_credit'],effects=[mod('Development Strategy',industrial_capacity_factory=.15,office_park_income_tax_modifier=-.05),building(140,'industrial_complex')],setup=1.5,source='economy',desc='Manufacturing offers a broader export base and less seasonal employment. Its equipment and long construction schedules tie up credit that could otherwise serve commerce and tourism.')
 add('economy','island_links','Island Transport and Services',-2,3,pre=['visitor_credit'],effects=[building(143,'infrastructure'),mod('Development Strategy',office_park_income_tax_modifier=.05,bureaucracy_cost_multiplier_modifier=.02)],setup=.75,source='economy',desc='Island communities need reliable links to the mainland before visitor spending can sustain local businesses. Maintaining those links remains a public obligation beyond the summer season.')
 add('economy','industrial_standards','Industrial Standards and Suppliers',2,3,pre=['industrial_credit'],effects=[research('CAT_industry',.5,1),mod('Development Strategy',production_factory_max_efficiency_factor=.10,education_cost_multiplier_modifier=.03)],setup=.5,source='economy',desc='Greek manufacturers must meet consistent standards and develop domestic suppliers. Better production discipline depends on continuing technical instruction.')
 add('economy','rural_water','Water and Rural Productivity',0,4,pre=[('island_links','industrial_standards')],effects=[building(139,'infrastructure'),remove('Uneven Development'),mod('Development Strategy',agricolture_productivity_modifier=.10)],setup=1,source='economy',desc='Irrigation, local roads and storage can connect agricultural districts to expanding urban markets. These works broaden the gains of growth without treating rural Greece as a reserve of departing labor.')
 add('economy','farm_cooperatives','Modernize the Cooperatives',-2,5,pre=['rural_water'],ex=['commercial_farming'],effects=[mod('Development Strategy',agricolture_productivity_modifier=.15,bureaucracy_cost_multiplier_modifier=.05)],setup=.5,source='economy',desc='Cooperative purchasing and processing give smaller farmers access to equipment and distribution. Public supervision also carries administrative costs and risks protecting inefficient organizations.')
 add('economy','commercial_farming','Competitive Farm Credit',2,5,pre=['rural_water'],ex=['farm_cooperatives'],effects=[mod('Development Strategy',agricolture_productivity_modifier=.10,office_park_income_tax_modifier=.08,stability_factor=-.03)],setup=.5,source='economy',desc='Commercial credit rewards farms able to mechanize and sell at scale. The strongest producers gain quickly while smaller households face a harsher adjustment.')
 add('economy','shipyards','Piraeus and the Shipbuilding Base',0,6,pre=[('farm_cooperatives','commercial_farming')],effects=[building(141,'dockyard'),mod('Development Strategy',dockyard_productivity=.10,bureaucracy_cost_multiplier_modifier=.02)],setup=1.5,source='economy',desc='A maritime country should retain more repair, engineering and construction work in its own ports. The shipbuilding base needs dependable public infrastructure as well as private orders.')
 add('economy','shipping','Merchant Shipping Services',-2,7,pre=['shipyards'],ex=['domestic_marine_supply'],effects=[mod('Development Strategy',office_park_income_tax_modifier=.12,foreign_influence_defense_modifier=-.08)],setup=.5,source='economy',desc='Shipping services bring earnings and expertise from a world-spanning Greek fleet. Dependence on international owners and foreign demand limits the state influence over those earnings.')
 add('economy','domestic_marine_supply','A Domestic Marine Supply Chain',2,7,pre=['shipyards'],ex=['shipping'],effects=[building(142,'industrial_complex'),mod('Development Strategy',industrial_capacity_dockyard=.12,office_park_income_tax_modifier=-.04)],setup=1.5,source='economy',desc='Domestic equipment and maintenance suppliers can keep more value in Greek yards. Building this network costs more than relying on established international suppliers.')

 # Twelve military focuses: land institutions and the combined Aegean air/naval problem.
 add('defence','joint_staff','A Joint Defence Staff',0,0,effects=[remove('Divided Officer Corps'),mod('Defence Programme',planning_speed=.15,bureaucracy_cost_multiplier_modifier=.05)],setup=.5,source='security',desc='Political rivalries inside the services have damaged confidence in joint command. A professional planning staff can restore coordination while enlarging the permanent military administration.')
 add('defence','army_school','Army Schools and Staff Courses',-4,1,pre=['joint_staff'],effects=[doctrine(),xp('army',25)],setup=.5,weekly=.002,source='security',desc='Training officers for combined operations matters more than multiplying political appointments. Staff education requires a continuing commitment to instructors and facilities.')
 add('defence','aegean_command','An Aegean Command',4,1,pre=['joint_staff'],effects=[research('CAT_naval',.5,1),xp('navy',25)],setup=.5,weekly=.002,source='security',desc='The islands and sea lanes demand coordinated naval and air planning. A standing command gives that mission institutional weight and a recurring cost.')
 add('defence','territorial_army','Depth Through Territorial Forces',-6,2,pre=['army_school'],ex=['professional_cadres'],effects=[mod('Defence Programme',army_org_factor=.15,training_time_factor=.15)],setup=.5,source='security',desc='Territorial formations provide a resilient framework for defending difficult ground. Their wider intake takes longer to train to a common standard.')
 add('defence','professional_cadres','Professional Cadres',-2,2,pre=['army_school'],ex=['territorial_army'],effects=[mod('Defence Programme',army_org_factor=.05,training_time_factor=-.15,max_planning_factor=.10)],setup=.75,weekly=.003,source='security',desc='A stronger professional cadre accelerates training and improves detailed preparation. Maintaining that cadre is more expensive than relying on a broad territorial establishment.')
 add('defence','sea_denial','Sea Denial and Coastal Defence',2,2,pre=['aegean_command'],ex=['sea_control'],effects=[mod('Defence Programme',navy_org_factor=.15,naval_invasion_prep_speed=-.20),research('CAT_naval',.5,1)],setup=.75,source='security',desc='Coastal defence and dispersed naval forces make hostile access to the Aegean costly. Concentration on denial leaves less capacity for expeditionary landings.')
 add('defence','sea_control','A Fleet for Sea Control',6,2,pre=['aegean_command'],ex=['sea_denial'],effects=[mod('Defence Programme',navy_org_factor=.08,naval_speed_factor=.10,amphibious_invasion=.10)],setup=1,weekly=.004,source='security',desc='A fleet able to operate beyond the immediate coast can protect shipping and support distant forces. Its readiness and logistics consume a larger share of national resources.')
 add('defence','army_industry','Army Workshops and Maintenance',-4,3,pre=[('territorial_army','professional_cadres')],effects=[building(140,'arms_factory'),research('CAT_infantry',.5,1)],setup=1.5,source='security',desc='Repair capacity and domestic workshops reduce the distance between an equipment order and a field formation. Their value depends on sustained technical competence, not a political procurement announcement.')
 add('defence','air_command','Air Defence of the Aegean',4,4,pre=['aegean_command'],effects=[xp('air',35),research('CAT_air',.5,1)],setup=.75,source='security',desc='Control of the air is inseparable from the defence of islands and sea lanes. Air staffs must choose where a limited force can achieve the greatest effect.')
 add('defence','interceptors','Concentrate on Interception',2,5,pre=['air_command'],ex=['close_support'],effects=[research('CAT_fighter',.5,2),mod('Defence Programme',research_speed_factor=.03,bureaucracy_cost_multiplier_modifier=.02)],setup=.5,source='security',desc='Interceptor training and aircraft development prioritize the protection of national airspace. The supporting radar and technical establishment must be maintained continuously.')
 add('defence','close_support','Concentrate on Battlefield Support',6,5,pre=['air_command'],ex=['interceptors'],effects=[research('CAT_air',.5,2),mod('Defence Programme',planning_speed=.20,naval_invasion_prep_speed=.15)],setup=.75,weekly=.003,source='security',desc='An air arm trained closely with land and naval forces can support a rapid operational decision. This approach accepts the continuing expense of specialized coordination.')
 add('defence','radar','Link the Radar Stations',4,6,pre=[('interceptors','close_support')],effects=[building(144,'radar_station'),research('CAT_electronics',.5,1)],setup=.75,source='security',desc='Linked reporting stations make a scattered island defence less fragmented. Radar works must be placed where Greece actually controls the land and can maintain the equipment.')

 # Eleven external-policy focuses, with real recipient decisions for all agreements.
 add('foreign','external_room','Recover Room for Diplomacy',0,0,effects=[mod('External Relations',foreign_influence_modifier=.10,political_power_factor=-.05)],weekly=.001,source='diplomacy',desc='Greece occupies an important strategic position but cannot assume that foreign governments will overlook its domestic settlement. Diplomatic room requires sustained attention and resources.')
 add('foreign','american_standard','American Standardization',-2,1,pre=['external_room'],ex=['french_option'],effects=[offer('usa')],source='usa',desc='American facilities and equipment have long shaped the Greek defence establishment. A renewed agreement trades access and dependence for training, technical support and revenue.')
 add('foreign','french_option','A Diversified Defence Partnership',2,1,pre=['external_room'],ex=['american_standard'],effects=[offer('france')],source='france',desc='French procurement and training offer a second route to modern equipment. Diversification reduces reliance on one supplier while increasing the demands of technical support.')
 add('foreign','aegean_talks','Negotiate Aegean Procedures',-2,2,pre=[('american_standard','french_option')],ex=['aegean_deterrence'],effects=[offer('turkey')],source='aegean',desc='Working procedures at sea and in the air can reduce the risk of an accidental confrontation. Each government must accept restraints on how it demonstrates its claims.')
 add('foreign','aegean_deterrence','Deterrence in the Aegean',2,2,pre=[('american_standard','french_option')],ex=['aegean_talks'],effects=[mod('External Relations',navy_org_factor=.08,planning_speed=.20,office_park_income_tax_modifier=-.05)],setup=.5,weekly=.003,source='aegean',desc='Greece can invest in a more visible posture instead of a bilateral restraint agreement. Readiness carries economic costs and does not settle the underlying maritime disputes.')
 add('foreign','association','Restore European Association',0,3,pre=[('aegean_talks','aegean_deterrence')],effects=[offer('association')],require='Representative institutions, legal political competition and all current EC member governments approval.',source='eec',desc='The association signed in 1961 survived in restricted form after the coup, but its political and financial development stalled. Restoration requires a credible democratic settlement and agreement from the Community governments.')
 add('foreign','accession','Apply for Community Membership',0,4,pre=['association'],effects=[offer('accession')],require='European association is active. Greece meets native membership conditions. Every current Community member consents.',source='eec',desc='Membership carries political obligations as well as economic opportunity. Greece applies through the existing Community institutions and accepts their adopted rules rather than declaring itself a member.')
 add('foreign','yugoslav_corridor','A Balkan Transit Understanding',-4,5,pre=['external_room'],effects=[offer('yugoslavia')],source='balkans',desc='Transit through Yugoslavia links Greek ports with markets beyond the northern frontier. Reliable infrastructure benefits both sides but requires each government to commit to practical cooperation.')
 add('foreign','bulgarian_trade','A Northern Commercial Opening',4,5,pre=['external_room'],effects=[offer('bulgaria')],source='balkans',desc='The disappearance of Bulgarian territorial claims created space for more ordinary relations. Commercial cooperation can broaden trade without pretending that the two alliance systems have merged.')
 add('foreign','british_guarantee','Coordinate with the British Guarantor',-2,6,pre=['yugoslav_corridor'],effects=[offer('britain')],source='guarantee',desc='Britain remains a guarantor of Cyprus and holds sovereign base areas on the island. Coordination can strengthen crisis communications without granting Greece control of British forces or bases.')
 add('foreign','skills_return','A German Technical Exchange',2,6,pre=['bulgarian_trade'],effects=[offer('germany')],source='migration',desc='The labor relationship with West Germany can also support technical instruction and returning skills. A funded exchange gives both countries a concrete interest without scripting a population transfer.')

 # Ten junta focuses; Papadopoulos and Ioannidis are an internal choice, not two invented parties.
 add('junta','officer_compact','The Officer Compact',0,0,effects=[mod('Military Government Programme',army_org_factor=.08,political_power_factor=.10,research_speed_factor=-.05)],desc='The dictatorship rests on an officer coalition rather than an ordinary governing party. Preserving that coalition strengthens command but keeps the state dependent on military arbitration.')
 add('junta','papadopoulos','Papadopoulos and the Cabinet',-2,1,pre=['officer_compact'],ex=['security_directorate'],leader='Georgios Papadopoulos',effects=[mod('Military Government Programme',production_speed_buildings_factor=.10,bureaucracy_cost_multiplier_modifier=.05)],desc='Papadopoulos concentrates political authority around his cabinet and the development administration. Economic coordination offers a positive programme, while patronage makes that apparatus costly.')
 add('junta','security_directorate','The Security Directorate',2,1,pre=['officer_compact'],ex=['papadopoulos'],effects=[action('An internal leadership change brings Ioannidis to actual power','country_event = { id = COLDWAR_GRE_R2_politics.10 }'),mod('Military Government Programme',foreign_influence_defense_modifier=.15,office_park_income_tax_modifier=-.08)],require='The hardliners have secured control of the military government. This is an alternative leadership struggle, not the January 1970 starting leader.',desc='Ioannidis and the security apparatus reject a civilian political opening. Their ascent must be a real change of leadership, with the diplomatic exposure that a harder dictatorship entails.')
 add('junta','managed_opening','A Managed Political Opening',-4,2,pre=['papadopoulos'],ex=['military_technocrats'],effects=[mod('Military Government Programme',research_speed_factor=.08,foreign_influence_modifier=.10,political_power_factor=-.10)],desc='A controlled opening seeks expertise and international credibility without immediately surrendering the regime. Every concession also loosens the instruments of personal command.')
 add('junta','military_technocrats','Technocrats Under Military Tutelage',0,2,pre=['papadopoulos'],ex=['managed_opening'],effects=[building(141,'industrial_complex'),mod('Military Government Programme',production_factory_efficiency_gain_factor=.15,education_cost_multiplier_modifier=.05)],setup=1.5,desc='The cabinet can instead make development the substitute for political participation. Industrial expertise grows inside an administration whose military sponsors retain the final veto.')
 add('junta','loyal_command','Promotion Through Loyalty',2,3,pre=['security_directorate'],ex=['service_council'],effects=[mod('Military Government Programme',army_org_factor=.10,navy_org_factor=-.10)],require='Dimitrios Ioannidis actually controls the government.',desc='A loyal army command is less likely to challenge the security leadership. The price is renewed distrust from naval officers and other institutions excluded from promotion.')
 add('junta','service_council','Bargain with the Services',6,3,pre=['security_directorate'],ex=['loyal_command'],effects=[mod('Military Government Programme',navy_org_factor=.12,army_org_factor=-.05),xp('navy',25)],require='Dimitrios Ioannidis actually controls the government.',desc='An inter-service settlement gives naval professionalism room to recover. The army security network must accept that it cannot monopolize every appointment.')
 add('junta','civil_ministries','Civilian Ministries, Military Veto',-2,4,pre=[('managed_opening','military_technocrats')],effects=[research('CAT_industry',.5,2),mod('Military Government Programme',bureaucracy_cost_multiplier_modifier=.03)],setup=.5,desc='Civilian specialists can administer complex programmes without holding sovereign political authority. Their inclusion makes the state more capable, not yet representative.')
 add('junta','security_budget','A Permanent Security Establishment',4,5,pre=[('loyal_command','service_council')],effects=[mod('Military Government Programme',max_planning_factor=.15,political_power_factor=.10,office_park_income_tax_modifier=-.05)],weekly=.003,require='Dimitrios Ioannidis actually controls the government.',desc='A permanent security establishment offers the leadership a stronger instrument for ambitious foreign policy. It also absorbs resources and increases the economic cost of political isolation.')
 add('junta','enduring_order','An Order Beyond the Barracks',0,7,pre=[('civil_ministries','security_budget')],effects=[mod('Military Government Programme',stability_factor=.08,research_speed_factor=.03,political_power_factor=-.10)],setup=.5,desc='An enduring regime needs institutions able to outlast one circle of officers. Establishing predictable administration restrains arbitrary executive intervention even while elections remain absent.')

 # Eight conservative focuses, respecting ERE in 1970 and the later native ND identity.
 add('right','conservative_mandate','A Civilian Conservative Mandate',0,0,effects=[mod('Conservative Reconstruction',foreign_influence_defense_modifier=.10,office_park_income_tax_modifier=.08,bureaucracy_cost_multiplier_modifier=.03)],desc='The conservative tradition must prove that civilian authority can deliver stability without a military veto. Economic confidence and institutional credibility become the basis of its mandate.')
 add('right','karamanlis','Call Karamanlis Home',-2,1,pre=['conservative_mandate'],ex=['kanellopoulos'],effects=[action('Select Karamanlis through the existing Greek leader system','country_event = { id = COLDWAR_GRE_R2_politics.20 }'),mod('Conservative Reconstruction',foreign_influence_modifier=.15,political_power_factor=-.05)],desc='Karamanlis offers international standing and an established conservative constituency. His return also challenges politicians who kept the party tradition alive during exile.')
 add('right','kanellopoulos','The Kanellopoulos Tradition',2,1,pre=['conservative_mandate'],ex=['karamanlis'],effects=[mod('Conservative Reconstruction',stability_factor=.08,army_org_factor=.05,research_speed_factor=-.03)],desc='A constitutional conservative leadership can build on Kanellopoulos and the pre-coup parliamentary tradition. Its reassuring continuity also leaves less room for a decisive break with older institutions.')
 add('right','european_credit','Restore European Credit',-2,2,pre=['karamanlis'],effects=[research('CAT_industry',.5,2),mod('Conservative Reconstruction',bureaucracy_cost_multiplier_modifier=.03)],setup=.5,desc='European confidence rests on political credibility and concrete reforms. The conservative government prepares the economy for a negotiated relationship rather than treating admission as a unilateral right.')
 add('right','constitutional_right','Constitutional Conservatism',2,2,pre=['kanellopoulos'],effects=[mod('Conservative Reconstruction',political_power_factor=.10,foreign_influence_defense_modifier=.10,bureaucracy_cost_multiplier_modifier=.03)],desc='Conservative authority is rooted in law, parliament and a disciplined administration. The same formal safeguards slow decisions that an authoritarian cabinet could simply impose.')
 add('right','enterprise','Competitive Greek Enterprise',0,3,pre=[('european_credit','constitutional_right')],effects=[building(140,'industrial_complex'),mod('Conservative Reconstruction',production_factory_max_efficiency_factor=.10)],setup=1.5,desc='Competitive firms need productive investment rather than permanent protection from change. A stronger manufacturing base gives the civilian right a tangible economic programme.')
 add('right','tax_compliance','Tax Compliance and Sound Accounts',-2,4,pre=['enterprise'],ex=['productive_credit'],effects=[mod('Conservative Reconstruction',office_park_income_tax_modifier=.12,bureaucracy_cost_multiplier_modifier=.05)],setup=.5,desc='Reliable tax collection strengthens public finances without relying on emergency levies. The bureaucracy needed to enforce the rules must itself be funded.')
 add('right','productive_credit','Credit for Productive Investment',2,4,pre=['enterprise'],ex=['tax_compliance'],effects=[mod('Conservative Reconstruction',production_speed_industrial_complex_factor=.18,office_park_income_tax_modifier=-.06),research('CAT_industry',.5,1)],setup=1,desc='Preferential credit can accelerate investment in productive firms. Its benefits arrive before the state recovers the revenue it has forgone.')

 # Six Centre Union focuses.
 add('centre','liberal_mandate','Rebuild the Liberal Centre',0,0,effects=[mod('Liberal Reconstruction',stability_factor=.05,foreign_influence_defense_modifier=.10,bureaucracy_cost_multiplier_modifier=.05)],desc='The Centre Union tradition joins parliamentary legitimacy with administrative reform. Rebuilding that coalition requires institutions able to mediate its many constituencies.')
 add('centre','professional_service','A Professional Civil Service',0,1,pre=['liberal_mandate'],effects=[research('CAT_industry',.5,2),mod('Liberal Reconstruction',research_speed_factor=.05,political_power_factor=-.05)],setup=.75,desc='Professional recruitment and reliable public records reduce the role of personal patronage. Ministers lose some discretion as expertise and procedure gain authority.')
 add('centre','parliament_first','Parliament Before Palace',-2,2,pre=['professional_service'],ex=['liberal_compromise'],effects=[mod('Liberal Reconstruction',political_power_factor=.15,foreign_influence_defense_modifier=.10,stability_factor=-.03)],desc='Parliamentary supremacy promises a clear answer to the conflicts of the 1960s. It also forces a confrontation with constituencies attached to an independent royal role.')
 add('centre','liberal_compromise','A Broad Constitutional Compromise',2,2,pre=['professional_service'],ex=['parliament_first'],effects=[mod('Liberal Reconstruction',stability_factor=.10,army_org_factor=.05,political_power_factor=-.10)],desc='A broad settlement can reassure the services and constitutional conservatives. Its breadth limits the freedom of the government that must uphold it.')
 add('centre','provinces','Bring Development to the Provinces',0,3,pre=[('parliament_first','liberal_compromise')],effects=[building(139,'infrastructure'),mod('Liberal Reconstruction',agricolture_productivity_modifier=.08)],setup=.75,desc='Provincial infrastructure gives the parliamentary center a practical purpose beyond managing Athens. Better local connections make development visible outside the capital.')
 add('centre','universities','Free and Capable Universities',0,4,pre=['provinces'],effects=[remove('Emigration and Technical Gaps'),mod('Liberal Reconstruction',research_speed_factor=.08,education_cost_multiplier_modifier=.10)],setup=1,desc='Universities require freedom to recruit and to argue, as well as dependable funding. Restoring that environment is an investment in expertise rather than a promise of immediate political obedience.')

 # Eight PAK/PASOK focuses. Later identity changes use the existing dated names.
 add('socialist','national_change','National Independence and Social Change',0,0,effects=[mod('National and Social Programme',foreign_influence_defense_modifier=.15,stability_factor=.05,office_park_income_tax_modifier=-.05)],desc='The Papandreou movement connects social reform with independence from external tutelage. Its programme deliberately challenges established owners and foreign partners.')
 add('socialist','social_contract','A Social Contract',0,1,pre=['national_change'],effects=[mod('National and Social Programme',stability_factor=.08,bureaucracy_cost_multiplier_modifier=.05),remove('Suppressed Political Life')],setup=.75,desc='Labor and excluded constituencies must gain a legal voice if popular sovereignty is to be more than a slogan. A government that incorporates them also accepts new administrative obligations.')
 add('socialist','public_credit','Public Control of Strategic Credit',-2,2,pre=['social_contract'],ex=['negotiated_development'],effects=[building(141,'industrial_complex'),mod('National and Social Programme',industrial_capacity_factory=.15,office_park_income_tax_modifier=-.10,bureaucracy_cost_multiplier_modifier=.05)],setup=2,desc='Public control directs credit toward sectors the government considers strategic. It can expand industrial output while reducing private financial earnings and increasing administrative exposure.')
 add('socialist','negotiated_development','A Negotiated Development Compact',2,2,pre=['social_contract'],ex=['public_credit'],effects=[building(140,'offices'),mod('National and Social Programme',production_speed_industrial_complex_factor=.15,office_park_income_tax_modifier=.08,foreign_influence_defense_modifier=-.08)],setup=1.5,desc='A negotiated compact draws investment from private enterprise while securing public commitments. The state gains a wider economic coalition but accepts continued dependence on its partners.')
 add('socialist','national_health','A National Health Service',0,3,pre=[('public_credit','negotiated_development')],effects=[mod('National and Social Programme',stability_factor=.08,industrial_capacity_factory=.05,health_cost_multiplier_modifier=.15)],setup=2,source='social_policy',desc='A national health service makes access to care a public responsibility rather than an accident of locality or income. The resulting security and productive gains require a larger recurring health budget.')
 add('socialist','workers_voice','Workers in Public Administration',0,4,pre=['national_health'],effects=[mod('National and Social Programme',political_power_factor=.10,bureaucracy_cost_multiplier_modifier=.05),research('CAT_industry',.5,1)],setup=.5,desc='Worker representation ties the administration to the social coalition that sustains the government. Consultation can improve policy acceptance while making administration more demanding.')
 add('socialist','independent_diplomacy','An Independent Foreign Policy',-2,5,pre=['workers_voice'],ex=['western_bargain'],effects=[mod('National and Social Programme',foreign_influence_defense_modifier=.15,navy_org_factor=.05,research_speed_factor=-.05)],desc='A more independent policy reduces the influence of established patrons without assuming that alliance membership must vanish. Greater autonomy can restrict access to some external expertise.')
 add('socialist','western_bargain','Renegotiate the Western Bargain',2,5,pre=['workers_voice'],ex=['independent_diplomacy'],effects=[mod('National and Social Programme',research_speed_factor=.08,office_park_income_tax_modifier=.05,foreign_influence_defense_modifier=-.10)],desc='The government can instead use its social mandate to seek better terms within the Western relationship. Access to capital and technology comes with continued external influence.')

