 add('left','left_mandate','The Communist Left in Government',0,0,effects=[mod('Left Government Programme',industrial_capacity_factory=.08,research_speed_factor=.05,office_park_income_tax_modifier=-.05)],desc='A legal communist government must translate an underground tradition into public institutions. Industrial planning and research take precedence over established commercial interests.')
 add('left','civil_war_families','Rehabilitate Civil War Families',0,1,pre=['left_mandate'],effects=[remove('Civil War Inheritance'),mod('Left Government Programme',stability_factor=.08,political_power_factor=-.05)],desc='Rehabilitation addresses exclusions that outlasted the fighting itself. The settlement strengthens civic belonging while restricting the partisan use of the state.')
 add('left','orthodox_plan','An Orthodox Planning Line',-2,2,pre=['civil_war_families'],ex=['left_front'],effects=[mod('Left Government Programme',industrial_capacity_factory=.15,dockyard_productivity=.05,office_park_income_tax_modifier=-.10)],setup=1.5,desc='A more orthodox line concentrates authority over industrial priorities. It delivers a stronger production programme at the expense of commercial flexibility.')
 add('left','left_front','A Broad Democratic Left Front',2,2,pre=['civil_war_families'],ex=['orthodox_plan'],effects=[mod('Left Government Programme',research_speed_factor=.10,stability_factor=.08,political_power_factor=-.10)],desc='Cooperation with the non-orthodox left, including KKE Interior constituencies, broadens the political base. Pluralism brings expertise and legitimacy while limiting the governing party freedom of command.')
 add('left','research_institutes','Industrial Research Institutes',0,3,pre=[('orthodox_plan','left_front')],effects=[research('CAT_industry',.5,2),mod('Left Government Programme',education_cost_multiplier_modifier=.05)],setup=1,desc='Applied research can connect the planned industrial base with sustained technical progress. Institutes need stable funding and genuine professional competence.')
 add('left','eastern_terms','Eastern Industrial Terms',0,4,pre=['research_institutes'],effects=[offer('soviet')],source='balkans',desc='An industrial agreement with the Soviet Union offers another source of technical cooperation. The terms must be accepted by both governments and need not turn Greece into a subordinate state.')

 # Six monarchist focuses, distinct from a mere conservative party label.
 add('crown','royal_mandate','The Crown and the Nation',0,0,effects=[mod('Royal Constitutional Programme',political_power_factor=.10,army_org_factor=.05,foreign_influence_defense_modifier=-.05)],desc='Royalists claim a source of legitimacy above ordinary party competition. That claim can rally supporters while reviving arguments over the Crown foreign connections.')
 add('crown','constantine','A Constitutional Return for Constantine',0,1,pre=['royal_mandate'],effects=[action('Confirm the King through the existing monarchist leader system','country_event = { id = COLDWAR_GRE_R2_politics.30 }'),mod('Royal Constitutional Programme',stability_factor=.05,political_power_factor=-.05)],require='A freely accepted constitutional restoration, or a publicly mandated monarchist settlement.',desc='The King return requires an agreed constitutional position, not a claim that the failed countercoup never happened. The invitation binds the restored institution to a public settlement.')
