 add('crown','royal_veto','An Active Royal Executive',2,2,pre=['constantine'],ex=['parliamentary_king'],effects=[mod('Royal Constitutional Programme',political_power_factor=.20,army_org_factor=.05,stability_factor=-.08,research_speed_factor=-.05)],desc='An active Crown offers a more decisive executive center. Reopening the question of royal intervention also revives the polarization that destabilized earlier parliamentary government.')
 add('crown','services_reconciled','Reconcile the Services',0,3,pre=[('parliamentary_king','royal_veto')],effects=[mod('Royal Constitutional Programme',navy_org_factor=.10,bureaucracy_cost_multiplier_modifier=.03),xp('navy',30)],setup=.5,desc='The royalist tradition is strongest in parts of the naval establishment but cannot substitute for inter-service confidence. Reconciliation requires professional representation and a funded command structure.')
 add('crown','dynastic_settlement','A Durable Constitutional Settlement',0,4,pre=['services_reconciled'],effects=[remove('Civil War Inheritance'),mod('Royal Constitutional Programme',stability_factor=.08,foreign_influence_defense_modifier=.10,office_park_income_tax_modifier=-.03)],setup=.5,desc='A durable settlement must make loyal opposition compatible with loyalty to the state. Patronage and public commitments are the cost of consolidating the restored institution.')

 # Thirteen Cyprus focuses, preserving all nine existing shared-focus IDs and crisis APIs.
 old=json.loads((ROOT/'tools/cyprus_1970_rework/approved_design.json').read_text('utf8'))
 actors={a['key']:a for a in old['actor_focuses']if a['tag']=='GRE'}
 placement={'gre_officers':(0,0),'gre_treaty':(-2,1),'gre_network':(2,1),'gre_consult':(-4,2),'gre_withdraw':(0,3),'gre_coup':(4,3),'gre_response':(0,7),'gre_volunteers':(-2,8),'gre_escalate':(2,8)}
 actor_descriptions={
 'gre_officers':'The Greek mission has institutional influence inside the Cypriot National Guard. Professional cooperation and political intervention are different uses of the same presence.',
 'gre_treaty':'Respect for the Republic protects a cooperative Greek position without attempting to command Cypriot political life. Influence is exercised through accepted institutions rather than a clandestine veto.',
 'gre_network':'An officer network offers leverage over the government in Nicosia. Supporting it spends Greek political capital and creates a crisis which the other guarantors can answer.',
 'gre_consult':'The guarantors receive a real request for consultation. Neither Turkey nor Britain is assumed to agree with the Greek government merely because Athens completed a focus.',
 'gre_withdraw':'Withdrawing support for the clandestine network reduces Greek leverage but gives the Republic room to restore confidence. This choice is available before a coup attempt is launched.',
 'gre_coup':'A coup can replace the Cypriot government if the officer network overcomes its prepared defence. Success creates a short strategic opening, not Greek ownership or a guaranteed victory over Turkey.',
 'gre_response':'An actual Turkish-Cypriot war confronts Athens with a distinct choice. Limited aid and direct participation offer different benefits and dangers.',
 'gre_volunteers':'A volunteer mission supports Cyprus while limiting the formal Greek commitment. It uses real Greek formations through native diplomacy and remains subject to engine deployment rules.',
 'gre_escalate':'Direct entry puts Greek forces on the Cypriot side against Turkey. Both prior NATO members leave before Greece joins, and return through the existing guarded process after both relevant wars end.'}
 for key in actors:
  a=actors[key];dx,y=placement[key]
  add('cyprus',key,a['title'],dx,y,pre=a['pre'],ex=a['exclusive'],effects=[{'type':'existing_actor','key':key,'effects':a['effects'],'helper':'COLDWAR_CYP_R2_ACT_'+key+'_apply'}],cost=a['cost'],require=a['requirements'],desc=actor_descriptions[key],source='cyprus')
  nodes[-1]['id']=a['id'];nodes[-1]['existing_actor']=True
 add('cyprus','island_trade','Civilian Cooperation with Cyprus',-2,3,pre=['gre_treaty'],effects=[offer('cyprus_trade')],source='cyprus',desc='Civilian trade and technical cooperation give Greece an enduring stake in a stable Republic. Cyprus receives the actual terms and may accept or refuse them.')
 add('cyprus','staff_network','Prepare the Cypriot Officer Network',4,2,pre=['gre_network'],effects=[action('Cyprus officer penetration +10','CYP = { add_to_variable = { COLDWAR_CYP_R2_officer_penetration = 10 } }'),temporary('Forward Operational Planning',180,planning_speed=.20,office_park_income_tax_modifier=-.05)],setup=.75,require='The Greek network and officer footprint are active. No coup has yet been launched.',source='cyprus',desc='A prepared network gives the coup a stronger chance than political sponsorship alone. The investment is sunk if Cypriot institutions contain it or Athens later withdraws support.')
 add('cyprus','operational_initiative','Exploit the Operational Initiative',4,5,pre=['gre_coup'],effects=[temporary('Operational Initiative in Cyprus',180,planning_speed=.25,max_planning_factor=.10,naval_invasion_prep_speed=.15,office_park_income_tax_modifier=-.10,foreign_influence_defense_modifier=-.10),doctrine('land_doctrine',.5,1)],weekly=.003,require='The actual coup succeeded, the coup government remains in power in Cyprus, and the two countries are at peace. Once only.',source='cyprus',desc='A successful coup briefly gives the Greek command greater freedom to prepare its next move. The advantage expires, while diplomatic exposure and the cost of readiness make delay expensive.')
 add('cyprus','guarantee_settlement','An Agreed Guarantor Settlement',-4,4,pre=['gre_consult'],effects=[offer('cyprus_settlement')],require='The Cypriot constitutional government is in office. Greece, Turkey, Britain and Cyprus must accept the security settlement.',source='guarantee',desc='A negotiated security settlement offers a durable alternative to a short military opening. It preserves Cypriot sovereignty and requires all four governments to accept their obligations.')
 # Replace the redundant final royal consolidation focus with independent emergency aid.
