 nodes=[f for f in nodes if f['key']!='dynastic_settlement']
 add('cyprus','reinforce_guard','Reinforce the National Guard',-4,0,effects=[offer('reinforcements')],cost=1,require='Cyprus is independent and consents. Greece has the complete personnel and equipment reserve. Cyprus owns and controls a valid deployment location. Greece and Cyprus are at peace and impose no embargo or sanctions on each other.',source='reinforcements',desc='Greek personnel and arms can reinforce the Cypriot National Guard before a landing decides the crisis. Two formed light infantry divisions pass into Cypriot command as soon as the Republic accepts. Greece gives up the men and weapons from its own reserves. The contribution supports the island while leaving Athens free to choose limited aid or full military intervention later.')
 # Consolidate three institutional follow-ups without deleting their rewards or forks.
 by_key={f['key']:f for f in nodes}
 for target,source in [('civil_ministries','enduring_order'),('security_budget','enduring_order'),('universities','provinces'),('social_contract','workers_voice')]:
  by_key[target]['effects']+=by_key[source]['effects']
