   f['effects'].append({'type':'conditional_transaction','label':'Upon Greek entry on the Cypriot side','after_helper':'COLDWAR_CYP_R2_ACT_gre_escalate_apply','post_conditions':['has_war_with = TUR','NOT = { has_war_with = CYP }','CYP = { has_war_with = TUR }','has_country_flag = COLDWAR_CYP_R2_greek_direct_entry_used'],'receipt':'COLDWAR_GRE_R2_expeditionary_command_issued','active_receipt':'COLDWAR_GRE_R2_expeditionary_command_active','once':True,'weekly_gdp_percent':.005,'effects':[temporary('Aegean Expeditionary Command',180,army_org_factor=.10,navy_org_factor=.10,planning_speed=.25,max_planning_factor=.15,amphibious_invasion=.20,naval_invasion_prep_speed=.30,office_park_income_tax_modifier=-.10)],'failure':'Grant no package or expense stream if successful war entry is not verified.'})
   f['weekly_lifetime']='The expeditionary charge and spirit last until the first of 180 days or the end of Greek-Turkish hostilities in this intervention. NATO separation lasts for the whole related war, even after this combat package expires.'
